CREATE TABLE event_reviews(event_id INTEGER, review_date DATE, original_impact VARCHAR, revised_impact VARCHAR, actual_outcome VARCHAR, lesson VARCHAR, created_at TIMESTAMP DEFAULT(current_timestamp), PRIMARY KEY(event_id, review_date));
CREATE TABLE events(id INTEGER PRIMARY KEY, event_timestamp TIMESTAMP WITH TIME ZONE NOT NULL, category VARCHAR NOT NULL, summary VARCHAR NOT NULL, impact VARCHAR, impact_reasoning VARCHAR, relevance VARCHAR, source_url VARCHAR, status VARCHAR DEFAULT('unreviewed'), created_at TIMESTAMP DEFAULT(current_timestamp), "source" VARCHAR DEFAULT('manual'));
CREATE TABLE knowledge(id VARCHAR PRIMARY KEY, category VARCHAR NOT NULL, "content" VARCHAR NOT NULL, evidence VARCHAR NOT NULL, confidence VARCHAR DEFAULT('low') NOT NULL, verification_status VARCHAR DEFAULT('hypothesis') NOT NULL, discovered_date DATE NOT NULL, last_verified_date DATE, invalidation_reason VARCHAR, created_at TIMESTAMP DEFAULT(current_timestamp), source_prediction_id INTEGER, tldr VARCHAR, related_knowledge_ids VARCHAR[]);
CREATE TABLE predictions(id INTEGER PRIMARY KEY, created_at TIMESTAMP WITH TIME ZONE NOT NULL, subject VARCHAR NOT NULL, deadline DATE NOT NULL, confidence DOUBLE NOT NULL, reasoning VARCHAR NOT NULL, falsification VARCHAR, outcome BOOLEAN, outcome_date DATE, outcome_notes VARCHAR, brier_score DOUBLE, category VARCHAR DEFAULT('market'), root_cause_category VARCHAR);
CREATE TABLE regime_assessments(date DATE PRIMARY KEY, vix_regime VARCHAR, vix_term_structure VARCHAR, credit_regime VARCHAR, yield_curve_regime VARCHAR, oil_regime VARCHAR, dollar_regime VARCHAR, overall VARCHAR, reasoning VARCHAR, created_at TIMESTAMP DEFAULT(current_timestamp), vix_value DOUBLE, vix3m_value DOUBLE, hy_spread_value DOUBLE, yield_curve_value DOUBLE, oil_value DOUBLE, usd_value DOUBLE);
CREATE TABLE skill_executions(id INTEGER PRIMARY KEY, skill_name VARCHAR NOT NULL, executed_at TIMESTAMP WITH TIME ZONE NOT NULL, result_summary VARCHAR, metadata VARCHAR, created_at TIMESTAMP DEFAULT(current_timestamp));
CREATE TABLE trades(id INTEGER PRIMARY KEY, instrument VARCHAR NOT NULL, direction VARCHAR NOT NULL, entry_date DATE NOT NULL, entry_price DOUBLE NOT NULL, exit_date DATE, exit_price DOUBLE, quantity INTEGER NOT NULL, pnl_usd DOUBLE, pnl_pct DOUBLE, commission_usd DOUBLE, holding_days INTEGER, regime_at_entry VARCHAR, vix_at_entry DOUBLE, brent_at_entry DOUBLE, confidence_at_entry DOUBLE, setup_type VARCHAR, entry_reasoning VARCHAR, exit_reasoning VARCHAR, discipline_score INTEGER, review_notes VARCHAR, prediction_id INTEGER, created_at TIMESTAMP DEFAULT(current_timestamp), status VARCHAR DEFAULT('filled'), breakeven_pct DOUBLE, cost_usd DOUBLE, pnl_net_usd DOUBLE, broker_ref VARCHAR, parent_trade_id INTEGER);
